'use server';

import { revalidateTag } from 'next/cache';

export async function createPost(formData: FormData) {
  // Extract data from the request
  const title = formData.get('title');
  const content = formData.get('content');

  // Perform your database mutation here
  // example: await db.post.create({ data: { title, content } });
  console.log('Post created:', { title, content });

  // Invalidate the cache tag
  // revalidateTag performs on-demand revalidation. It immediately purges the cache
  // associated with the "posts" tag. The next page load will be a cache miss,
  // causing Next.js to wait for a fresh fetch rather than serving stale content.
  revalidateTag('posts');
}

